// and answers 429 once the bucket is empty.
export function rateLimit(store: BucketStore, config: LimitsConfig): MiddlewareHandler {
  return async (c, next) => {
    const apiKey = c.req.header("x-api-key");
    if (!apiKey) {
      return c.json({ error: "missing API key" }, 401);
